"""Fixed-width EXPORT_ACCT record formatter."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


def _is_blank(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _fixed(value: Any, width: int) -> str:
    text = "" if value is None else str(value)
    return text[:width].ljust(width)


def _ann_rev_cents(value: Any) -> str:
    if _is_blank(value):
        value = 0

    decimal_value = Decimal(str(value).strip())
    precision = max(50, len(decimal_value.as_tuple().digits) + 10)

    with localcontext() as context:
        context.prec = precision
        cents = (decimal_value * Decimal(100)).to_integral_value(
            rounding=ROUND_HALF_UP
        )

    return str(int(cents)).zfill(15)


def format_account(row: dict) -> str:
    """Build one 77-character EXPORT_ACCT fixed-width record."""
    cred_hold = row.get("CRED_HOLD", "")
    if _is_blank(cred_hold):
        cred_hold = "N"
    else:
        cred_hold = str(cred_hold)

    create_dt = row.get("CREATE_DT", "")
    if _is_blank(create_dt):
        create_dt = "00000000"
    else:
        create_dt = str(create_dt)

    return (
        _fixed(row.get("ACCT_ID", ""), 10)
        + _fixed(row.get("ACCT_NM", ""), 40)
        + _fixed(row.get("REGION_CD", ""), 3)
        + _ann_rev_cents(row.get("ANN_REV", ""))
        + cred_hold
        + create_dt
    )
